/// <summary>
/// CB129 Cancellation of Open SO/PO lines
/// </summary>
[DataContractAttribute]
[SysOperationContractProcessing(classStr(METPurchCancelUIBuilder))]
class METPurchCancelContract implements SysOperationValidatable
{
    METChangeReasonCode reasonCode;
    Container purchLineRecords;
    METPOASNResp asnReceived;

}

Method.Source:
/// <summary>
/// CB129 Asn Received
/// </summary>
/// <param name = "_asnReceived">_asnReceived</param>
/// <returns>METPOASNResp</returns>
[DataMemberAttribute]
 public METPOASNResp parmAsnReceived(METPOASNResp _asnReceived = asnReceived)
{
    asnReceived = _asnReceived;
    return asnReceived;
}

/// <summary>
/// Reason code
/// </summary>
/// <param name = "_reasonCode">_reasonCode</param>
/// <returns>METChangeReasonCode</returns>

[DataMemberAttribute]
public METChangeReasonCode parmReasonCode(METChangeReasonCode _reasonCode = reasonCode)
{
    reasonCode = _reasonCode;
    return reasonCode;
}

/// <summary>
/// Purchase order line records
/// </summary>
/// <param name = "_purchLineRecords">parmPurchLineRecords</param>
/// <returns>container</returns>
[DataMemberAttribute,
SysOperationControlVisibilityAttribute(false)]
public container parmPurchLineRecords(container _purchLineRecords = purchLineRecords)
{
    purchLineRecords = _purchLineRecords;
    return purchLineRecords;
}

/// <summary>
/// validate
/// </summary>
/// <returns>boolean</returns>
public boolean validate()
{
    boolean ret = true;
    if(!this.parmReasonCode())
    {
        ret = checkFailed("@MET:ReasonCodeMandatory");
    }
    return ret;
}
